#include <cstddef>
#include <iostream>
#include <new>
#include <span>

int* reservar(int cantidad, bool provocarFallo) {
    if (provocarFallo) {
        throw std::bad_alloc{};
    }
    return new int[cantidad]{};
}

bool redimensionar(int*& base, int& cantidad, int nuevaCantidad, int relleno, bool provocarFallo) {
    if (nuevaCantidad < 0 || nuevaCantidad > 4 || relleno < 0 || relleno > 9) {
        return false;
    }
    if (nuevaCantidad == cantidad) {
        return true;
    }
    if (nuevaCantidad == 0) {
        delete[] base;
        base = nullptr;
        cantidad = 0;
        return true;
    }
    int* nuevo = nullptr;
    try {
        nuevo = reservar(nuevaCantidad, provocarFallo);
    } catch (const std::bad_alloc&) {
        return false;
    }
    // Conserva el prefijo, rellena lo añadido y publica sólo al terminar.
    // Sustituye esta limpieza provisional y el rechazo por la operación completa.
    delete[] nuevo;
    nuevo = nullptr;
    return false;
}

bool seleccionar(std::span<int> total, std::span<int>& vista, int inicio, int cantidad) {
    if (inicio < 0 || cantidad < 0) {
        return false;
    }
    const auto posicion = static_cast<std::size_t>(inicio);
    const auto longitud = static_cast<std::size_t>(cantidad);
    if (posicion > total.size() || longitud > total.size() - posicion) {
        return false;
    }
    vista = total.subspan(posicion, longitud);
    return true;
}

int main() {
    int ordenes = 0;
    if (!(std::cin >> ordenes) || ordenes < 1 || ordenes > 12) {
        return 1;
    }
    int* base = new int[2]{3, 6};
    int cantidad = 2;
    std::span<int> vista{base, 2};
    for (int i = 0; i < ordenes; ++i) {
        int operacion = 0;
        int a = 0;
        int b = 0;
        if (!(std::cin >> operacion >> a >> b)) {
            vista = std::span<int>{};
            delete[] base;
            base = nullptr;
            return 1;
        }
        const char* estado = "Orden";
        if (operacion == 1 || operacion == 2) {
            const int anterior = cantidad;
            const bool aceptado = redimensionar(base, cantidad, a, b, operacion == 2);
            if (aceptado && cantidad != anterior) {
                vista = std::span<int>{};
                if (base != nullptr) {
                    vista = std::span<int>{base, static_cast<std::size_t>(cantidad)};
                }
            }
            estado = aceptado ? "Aceptado" : "Rechazo";
        } else if (operacion == 3) {
            std::span<int> total;
            if (base != nullptr) {
                total = std::span<int>{base, static_cast<std::size_t>(cantidad)};
            }
            estado = seleccionar(total, vista, a, b) ? "Seleccion" : "Rechazo";
        } else if (operacion == 4) {
            if (a < 0 || a > 9) {
                estado = "Rechazo";
            } else {
                for (int& dato : vista) {
                    dato = a;
                }
                estado = vista.empty() ? "Vacio" : "Cambio";
            }
        }
        std::cout << "Estado:" << estado << ";Cantidad:" << cantidad
                  << ";Vista:" << vista.size() << ";Datos:";
        if (base == nullptr) {
            std::cout << 'X';
        } else {
            for (int j = 0; j < cantidad; ++j) {
                if (j != 0) {
                    std::cout << ',';
                }
                std::cout << base[j];
            }
        }
        std::cout << '\n';
    }
    vista = std::span<int>{};
    delete[] base;
    base = nullptr;
    cantidad = 0;
    std::cout << "Final:" << cantidad << ':' << vista.size() << '\n';
    return 0;
}

